package com.paradisemc.rokidfindmyphone;
import android.app.Activity;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;
public class AlarmActivity extends Activity { @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_DISMISS_KEYGUARD|WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);if(android.os.Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}setContentView(buildUi());} private View buildUi(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setPadding(dp(28),dp(28),dp(28),dp(28));r.setBackgroundColor(Color.rgb(10,20,25));TextView t=new TextView(this);t.setText("PHONE FOUND");t.setTextSize(34);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);t.setTypeface(t.getTypeface(),android.graphics.Typeface.BOLD);r.addView(t);TextView s=new TextView(this);s.setText("Triggered from your Rokid Glasses");s.setTextSize(18);s.setTextColor(Color.LTGRAY);s.setGravity(Gravity.CENTER);s.setPadding(0,dp(12),0,dp(36));r.addView(s);Button stop=new Button(this);stop.setText("STOP RINGING");stop.setTextSize(22);stop.setAllCaps(false);stop.setOnClickListener(v->{AlarmController.stop(this);finishAndRemoveTask();});r.addView(stop,new LinearLayout.LayoutParams(-1,dp(76)));return r;} private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);} }
